const B64_UPLOAD_CACHE = new Map();
const b64Key = str => {
  let h = 5381;
  const step = Math.max(1, Math.floor(str.length / 4000));
  for (let i = 0; i < str.length; i += step) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
  return `${str.length}_${h}`;
};

